(function(){"use strict";function map(value,inMin,inMax,outMin,outMax){return outMin+(value-inMin)*(outMax-outMin)/(inMax-inMin)}function initElement(el){if(el._danPolInit){return}el._danPolInit=true;var sensitivity=parseFloat(el.getAttribute("data-sensitivity"))||200;var rotationSpread=parseFloat(el.getAttribute("data-rotation"))||4;var cardEls=Array.from(el.querySelectorAll(".dan-polaroid__card"));var total=cardEls.length;if(total===0){return}var order=cardEls.slice();function updateTransforms(){for(var i=0;i<order.length;i++){var card=order[i];var frame=card.querySelector(".dan-polaroid__frame");var reverseIdx=total-i-1;var rz=reverseIdx*rotationSpread;var sc=1+i*0.05-total*0.05;card.style.zIndex=i+1;if(frame){frame.style.transform="rotateZ("+rz+"deg) scale("+sc+")"}}}function sendToBack(card){var idx=order.indexOf(card);if(idx<0){return}order.splice(idx,1);order.unshift(card);updateTransforms()}cardEls.forEach(function(card){var startX=0;var startY=0;var lastRawX=0;var lastRawY=0;var dragging=false;function onDown(e){if(e.button&&e.button!==0){return}dragging=true;startX=e.clientX;startY=e.clientY;lastRawX=0;lastRawY=0;card.classList.add("is-dragging");card.setPointerCapture(e.pointerId);e.preventDefault()}function onMove(e){if(!dragging){return}lastRawX=e.clientX-startX;lastRawY=e.clientY-startY;var ex=lastRawX*0.6;var ey=lastRawY*0.6;var rotX=map(ey,-100,100,60,-60);var rotY=map(ex,-100,100,-60,60);card.style.transform="translate("+ex+"px,"+ey+"px) rotateX("+rotX+"deg) rotateY("+rotY+"deg)"}function onUp(){if(!dragging){return}dragging=false;card.classList.remove("is-dragging");card.style.transform="";if(Math.abs(lastRawX)>sensitivity||Math.abs(lastRawY)>sensitivity){sendToBack(card)}lastRawX=0;lastRawY=0}card.addEventListener("pointerdown",onDown);card.addEventListener("pointermove",onMove);card.addEventListener("pointerup",onUp);card.addEventListener("pointercancel",onUp)});updateTransforms()}function initAll(){document.querySelectorAll(".dan-polaroid").forEach(function(el){el.removeAttribute("data-flickering");initElement(el)})}window.dancepad_polaroid=initAll;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initAll)}else{initAll()}})();
